"State","name":"Mississippi"}},{"@type":"City","name":"Vicksburg","containedInPlace":{"@type":"State","name":"Mississippi"}},{"@type":"City","name":"Columbus","containedInPlace":{"@type":"State","name":"Mississippi"}},{"@type":"City","name":"Greenville","containedInPlace":{"@type":"State","name":"Mississippi"}}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Home Insurance Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Claim Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/roof-hail-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Wind Damage Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/tornado-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane & Named Storm Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/hurricane-named-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Plumbing Loss Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/water-plumbing-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Loss Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/fire-smoke-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Claim Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/fallen-tree-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Storm & Freeze Appraisal","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/ice-storm-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://mississippiinsuranceappraiser.com/our-appraisal-services/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hurricane claims","Wind vs. flood allocation","Tornado damage","Xactimate estimates"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://mississippiinsuranceappraiser.com/#website","url":"https://mississippiinsuranceappraiser.com/","name":"Mississippi Insurance Appraiser","publisher":{"@id":"https://mississippiinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#webpage","url":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/","name":"Insurance Claim Terms Glossary | ACV, RCV, Umpire & More","description":"A searchable insurance claim terms glossary: actual cash value, holdback, named-storm deductible, MWUA, umpire and 40+ more terms.","inLanguage":"en-US","isPartOf":{"@id":"https://mississippiinsuranceappraiser.com/#website"},"about":{"@id":"https://mississippiinsuranceappraiser.com/#business"},"publisher":{"@id":"https://mississippiinsuranceappraiser.com/#business"},"dateModified":"2026-11-16","primaryImageOfPage":{"@type":"ImageObject","@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#primaryimage","url":"https://mississippiinsuranceappraiser.com/assets/img/photos/calculator.webp","width":960,"height":640},"breadcrumb":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},"mainEntity":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://mississippiinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Insurance claim terms","item":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/"}],"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance claim terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property at the time of loss, usually figured as replacement cost minus depreciation. Many policies pay this amount first and the rest after repairs.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense","description":"Extra costs you incur to live elsewhere while your home is unlivable after a covered loss, such as rent, hotel bills or higher food costs, above your normal spending.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the covered damage. It is the question an appraisal panel answers; coverage and policy interpretation are separate questions.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Anti-concurrent causation clause","description":"Policy language saying a loss is excluded if an excluded cause, such as flood, contributes to it, regardless of other causes acting at the same time. How it applies depends on the exact wording and facts.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, usually signed by both appraisers or by one appraiser and the umpire.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The section of a property policy that lets either side demand appraisal when you and the carrier disagree on the amount of a covered loss.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal demand","description":"The written notice, sent by you or the carrier, that invokes the appraisal clause and starts the policy’s timelines for naming appraisers.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A clause, common on commercial policies, that can reduce a payment if the property was insured for less than a required percentage of its value.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Competent and disinterested appraiser","description":"Typical policy wording for the qualifications each side’s appraiser must meet: able to value the loss and free of the kind of stake in the outcome that the policy forbids.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"The dwelling coverage on a homeowners policy, covering the house and attached structures. Percentage deductibles are usually figured from this limit.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, for detached buildings such as fences, sheds, detached garages and barns, often set as a percentage of Coverage A.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for contents such as furniture, clothing and electronics, which may be paid at actual cash value or replacement cost.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage D","description":"Loss of use coverage, which includes additional living expense and, on some forms, fair rental value when a rented unit becomes unlivable.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy showing the named insured, the property, coverage limits, deductibles and the policy period.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the policy pays. It is applied after the amount of loss is set.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition. It is subtracted from replacement cost to reach actual cash value.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing installed along roof edges to direct water into the gutters and away from the fascia. It is often required when a roof is replaced.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Flood (NFIP)","description":"Flood coverage, usually written through the National Flood Insurance Program, is separate from homeowners and wind policies and has its own claim rules.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation a carrier withholds from the first payment on a replacement cost claim until repairs are completed.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof underlayment applied at eaves, valleys and penetrations to resist leaks from ice dams and wind-driven rain.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as removing and replacing one square of shingles, with a quantity, unit price and total.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs reasonably match in color, texture or style. The answer depends on policy wording.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Mississippi Insurance Department","description":"The state agency that regulates insurers doing business in Mississippi and accepts consumer complaints. It is headed by an elected Commissioner of Insurance.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping a roof or drying out a wet room. Most policies require it.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"MWUA","description":"The Mississippi Windstorm Underwriting Association, a residual-market insurer of wind and hail coverage for property in the six southernmost counties.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Named-storm deductible","description":"A deductible that applies when a loss is caused by a named tropical storm or hurricane, as defined in the policy. It is often a percentage of Coverage A.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for the added cost of bringing repaired or rebuilt property up to current building codes. Limits are often a percentage of Coverage A.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit","description":"A general contractor’s charge for managing a job and earning a margin, often figured as a percentage on top of repair costs when several trades are needed.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible stated as a percentage of the dwelling limit rather than a flat dollar amount. On a larger home it can be a significant sum.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed and the facts of the loss. Some policies and flood programs require one within a set time.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Public adjuster","description":"A professional who represents a policyholder in presenting and negotiating a claim, typically for a percentage fee. An appraiser’s role is narrower and limited to the amount of loss.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that a replacement cost policy will pay back once repairs are finished and documented, usually within a stated period.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without a deduction for depreciation.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which a carrier says it is handling a claim while keeping the right to deny coverage later based on policy terms.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Roof square","description":"A unit of roof area equal to 100 square feet. Roofing materials and labor are usually priced per square.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what was damaged and what work is needed to repair it. Many appraisal disputes are really scope disputes.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on roofs with a steep pitch, often starting around a 7/12 slope, because the work is slower and needs more safety gear.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Storm surge","description":"The rise in sea level pushed ashore by a hurricane’s winds. Surge damage is generally treated as flood, not wind, under most policies.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an existing estimate after more damage is found or prices change during repairs.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Tree removal limit","description":"A cap on payment for removing fallen trees, which on many homeowners forms is a set amount per tree and per occurrence, and may apply only when a tree strikes a covered structure or blocks access.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Wind-driven rain","description":"Rain forced into a building by wind. Many policies cover interior water damage only if wind first creates an opening in the roof or walls.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by carriers, adjusters and contractors to price repairs line by line using regional price lists.","inDefinedTermSet":{"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}}],"@id":"https://mississippiinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}]}</script>
</head>
